class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        nodes = preorder.split(',')
        counter=1
        for i, node in enumerate(nodes):
            if node != '#':
                counter+=1
            else:
                if counter <= 1 and i != len(nodes) - 1:
                    return False
                counter-=1
        return counter == 0

class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        def split_iter(s, tok):
            start = 0
            for i in range(len(s)):
                if s[i] == tok:
                    yield s[start:i]
                    start = i + 1
            yield s[start:]

        if not preorder:
            return False

        depth, cnt = 0, preorder.count(',') + 1
        for tok in split_iter(preorder, ','):
            cnt -= 1
            if tok == "#":
                depth -= 1
                if depth < 0:
                    break
            else:
                depth += 1
        return cnt == 0 and depth < 0

